<script type="module">
import * as THREE from 'three';

const size = 216;
const scene = new THREE.Scene();
const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(size, size);
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

const ref = new THREE.OrthographicCamera(-108, 108, 108, -108, 1, 1200);
ref.position.set(0, 0, 420);
ref.lookAt(0, 0, 0);

const clamp = (x, low, high) => Math.max(low, Math.min(high, x));
const mix = (a, b, t) => a + (b - a) * t;
const smooth = t => {
  const u = clamp(t, 0, 1);
  return u * u * (3 - 2 * u);
};
const tau = 2 * Math.PI;
const point = (x, y, z = 0) => new THREE.Vector3(x - 108, 108 - y, z);

const backdrop = new Uint8Array(64 * 64 * 4);
let seed = 73;
for (let j = 0; j < 64; j++) {
  for (let i = 0; i < 64; i++) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    const x = (i + .5) / 64;
    const y = 1 - (j + .5) / 64;
    const floor = smooth((y - .76) / .23);
    const haze = 2.7 * Math.exp(-((x - .05) ** 2 / .24 + (y - .54) ** 2 / .23));
    const variation = .75 * Math.sin(25 * x + 14 * y) * Math.sin(18 * y - 9 * x);
    const v = 247.1 - haze - floor * (27 + 8 * x) + variation + 2.6 * (seed / 4294967296 - .5);
    const k = 4 * (64 * j + i);
    backdrop[k] = v - .8;
    backdrop[k + 1] = v + .65;
    backdrop[k + 2] = v - 1.1;
    backdrop[k + 3] = 255;
  }
}
const background = new THREE.DataTexture(backdrop, 64, 64, THREE.RGBAFormat);
background.colorSpace = THREE.SRGBColorSpace;
background.magFilter = THREE.LinearFilter;
background.minFilter = THREE.LinearFilter;
background.needsUpdate = true;
scene.background = background;

scene.add(new THREE.HemisphereLight(0xfffdf5, 0xd4c3ad, 1.82));
function directional(color, power, x, y, z) {
  const light = new THREE.DirectionalLight(color, power);
  light.position.set(x, y, z);
  scene.add(light);
}
directional(0xfff6e3, 1.84, -115, 180, 133);
directional(0xfff9ee, .50, 124, 23, 151);
directional(0xfff8e5, .84, 34, 105, -142);

const pivots = new WeakMap();
function joint(parent, name, x, y, z) {
  const group = new THREE.Group();
  const pivot = point(x, y, z);
  group.name = name;
  group.position.copy(pivot);
  if (pivots.has(parent)) group.position.sub(pivots.get(parent));
  pivots.set(group, pivot);
  parent.add(group);
  return group;
}
function addMesh(parent, name, geometry, material) {
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = name;
  mesh.position.copy(pivots.get(parent)).negate();
  parent.add(mesh);
  return mesh;
}
function closedCurve(coordinates) {
  return new THREE.CatmullRomCurve3(
    coordinates.map(([x, y]) => new THREE.Vector3(x, y, 0)), true
  );
}
const bellyCurve = closedCurve([
  [87,117],[96,111],[109,110.5],[123,113.5],[135,118],
  [146,124],[151,134],[148.5,149],[141.5,159.5],[129,167],
  [117,170.5],[105,166.5],[95.5,157],[89,144],[85.5,130]
]);
const bellyPoints = Array.from({length: 48}, (_, i) => {
  const p = bellyCurve.getPoint(i / 48);
  return new THREE.Vector2(p.x, p.y);
});

function skinMaterial(color, region) {
  const material = new THREE.MeshStandardMaterial({color, roughness: .91});
  material.customProgramCacheKey = () => `grain-${region}`;
  material.onBeforeCompile = shader => {
    shader.vertexShader = 'varying vec3 vCarvedPoint;\n' + shader.vertexShader;
    shader.vertexShader = shader.vertexShader.replace(
      '#include <begin_vertex>',
      '#include <begin_vertex>\nvCarvedPoint = position;'
    );
    shader.uniforms.bellyOutline = {value: bellyPoints};
    shader.uniforms.bellyColor = {value: new THREE.Color(0xd6b795)};
    shader.fragmentShader = `
      varying vec3 vCarvedPoint;
      uniform vec2 bellyOutline[48];
      uniform vec3 bellyColor;
      float hashCell(vec3 p) {
        p = fract(p * .1031);
        p += dot(p, p.yzx + 33.33);
        return fract((p.x + p.y) * p.z);
      }
      float fieldNoise(vec3 p) {
        vec3 c = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(
          mix(mix(hashCell(c), hashCell(c+vec3(1,0,0)), f.x),
              mix(hashCell(c+vec3(0,1,0)), hashCell(c+vec3(1,1,0)), f.x), f.y),
          mix(mix(hashCell(c+vec3(0,0,1)), hashCell(c+vec3(1,0,1)), f.x),
              mix(hashCell(c+vec3(0,1,1)), hashCell(c+vec3(1,1,1)), f.x), f.y), f.z);
      }
      float spot(vec2 p, vec2 c, vec2 r) {
        vec2 d = (p - c) / r;
        return exp(-dot(d,d));
      }
      float bellyDistance(vec2 p) {
        vec2 a = bellyOutline[47];
        float nearest = 1.e5;
        float side = 1.0;
        for (int i = 0; i < 48; ++i) {
          vec2 b = bellyOutline[i];
          vec2 e = b - a, w = p - a;
          vec2 d = w - e * clamp(dot(w,e) / dot(e,e), 0.0, 1.0);
          nearest = min(nearest, dot(d,d));
          bool crossing = (a.y > p.y) != (b.y > p.y);
          if (crossing && p.x < a.x + (p.y-a.y)*(b.x-a.x)/(b.y-a.y)) side = -side;
          a = b;
        }
        return side * sqrt(nearest);
      }
    ` + shader.fragmentShader;
    const coloring = {
      body: `
        float front = smoothstep(-1.0, 19.0, vCarvedPoint.z);
        float crown = spot(p,vec2(123,22),vec2(32,26));
        float chin = spot(p,vec2(114,78),vec2(26,12));
        float crease = spot(p,vec2(153,136),vec2(9,30));
        float hip = spot(p,vec2(133,179),vec2(41,16));
        diffuseColor.rgb *= 1.0 + .145*crown - front*(.145*chin+.23*crease+.15*hip);
        float d = bellyDistance(p) + .58 * (cloud-.5);
        float belly = (1.0-smoothstep(-.92,.9,d))*smoothstep(1.0,12.0,vCarvedPoint.z);
        vec3 tan = bellyColor * (1.0 - .155*smoothstep(132.0,171.0,p.y));
        diffuseColor.rgb = mix(diffuseColor.rgb, tan, belly);
      `,
      leftArm: `
        float inside = spot(p,vec2(87,133),vec2(7,33));
        diffuseColor.rgb *= 1.0 - .16*inside*frontFace;
      `,
      rightArm: `
        float crease = spot(p,vec2(149,129),vec2(13,23));
        float wrist = spot(p,vec2(153,178),vec2(12,11));
        diffuseColor.rgb *= 1.0 - frontFace*(.26*crease+.12*wrist);
      `,
      leg: `
        float low = smoothstep(161.0,210.0,p.y);
        diffuseColor.rgb *= .91 + .09*low;
      `,
      glove: `
        diffuseColor.rgb *= .91 + .18*spot(p,vec2(p.x,179),vec2(1,11));
      `
    }[region];
    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <color_fragment>',
      `#include <color_fragment>
       vec2 p = vec2(vCarvedPoint.x+108.0,108.0-vCarvedPoint.y);
       float cloud = fieldNoise(vCarvedPoint*.095);
       float fine = fieldNoise(vCarvedPoint*1.25);
       float frontFace = smoothstep(-3.0,15.0,vCarvedPoint.z);
       ${coloring}
       diffuseColor.rgb *= .953 + .063*cloud + .052*fine;`
    );
  };
  return material;
}

const gold = skinMaterial(0xd9ad42, 'body');
const leftGold = skinMaterial(0xd5a53d, 'leftArm');
const rightGold = skinMaterial(0xd9ab40, 'rightArm');
const legGold = skinMaterial(0xd5a440, 'leg');
const glove = skinMaterial(0x49463d, 'glove');

// Each loft row gives image height, center x, width radius, center z, and depth radius.
function profile(rows) {
  const slope = (i, k) => (rows[i + 1][k] - rows[i][k]) / (rows[i + 1][0] - rows[i][0]);
  const slopes = rows.map((row, i) => row.slice(1).map((v, k) => {
    if (i === 0) return slope(0, k + 1);
    if (i === rows.length - 1) return slope(i - 1, k + 1);
    const a = slope(i - 1, k + 1);
    const b = slope(i, k + 1);
    return a * b > 0 ? 2 * a * b / (a + b) : 0;
  }));
  return y => {
    const last = rows.length - 1;
    const yy = clamp(y, rows[0][0], rows[last][0]);
    let i = 0;
    while (i < last - 1 && yy > rows[i + 1][0]) i++;
    const a = rows[i], b = rows[i + 1];
    const h = b[0] - a[0], t = (yy - a[0]) / h, s = t * t * (3 - 2 * t);
    return a.slice(1).map((v, k) => mix(v, b[k + 1], s) +
      h * t * (1 - t) * ((1 - t) * slopes[i][k] - t * slopes[i + 1][k]));
  };
}

const bodyRows = [
  [12.1,125.0,.055,14,.05],[12.45,125.0,5.2,14,4.4],
  [13.5,124.6,10.2,13.5,8.5],[16.1,124.2,15.4,12.6,13.5],
  [20.3,124.1,20.5,11.7,17.4],[26,124.1,23.6,10,21.6],
  [33,124.1,25.8,9,25.0],[41,123.5,27.7,8.2,28.7],
  [47,122.8,30.0,6.4,31.7],[53.5,122.3,36.5,2.4,34.5],
  [61.8,122.1,41.0,-1.0,37.1],[72,123.0,44.5,-3.5,40.0],
  [85,124.9,45.4,-5,42.0],[98,126.1,44.7,-5.5,42.8],
  [112,126.4,42.9,-6.2,42.0],[126,127.5,41.8,-7.3,39.4],
  [139,129.4,39.7,-7.8,35.7],[151,131.0,36.6,-8.4,32.0],
  [162,132.5,33.0,-9.5,28.7],[174,133.8,27.7,-11.4,25.0],
  [185,134.0,20.0,-13.3,20.0],[194,134.5,10.5,-14,11.7],
  [198,134.5,.06,-14,.06]
];
const bodyProfile = profile(bodyRows);
function bell(x, y, cx, cy, wx, wy) {
  return Math.exp(-(((x - cx) / wx) ** 2 + ((y - cy) / wy) ** 2));
}
function ringPoint(at, y, angle, inset = 1, sculpt = false) {
  const [cx, width, cz, depth] = at(y);
  const sin = Math.sin(angle), cos = Math.cos(angle);
  const x = cx + width * sin * inset;
  let z = cz + depth * cos * inset;
  if (sculpt && cos > 0) {
    const bulge = 5.6 * bell(x,y,114,53,20,21) +
      2.6 * bell(x,y,118,30,9,8) +
      3.0 * bell(x,y,116,126,34,34) -
      3.0 * bell(x,y,133,78,28,9);
    const turn = 10.5 * Math.exp(-(((y - 43) / 30) ** 2)) + 5;
    z += inset * cos * cos * (bulge - turn * sin);
  }
  return point(x, y, z);
}
function faceZ(x, y) {
  const [cx, rx] = bodyProfile(y);
  const angle = Math.asin(clamp((x - cx) / rx, -1, 1));
  return ringPoint(bodyProfile, y, angle, 1, true).z;
}

const mouthCurve = closedCurve([
  [105.2,35.2],[109.6,33.35],[117.3,33.5],[125.8,35.2],
  [133.1,37.8],[137.6,40.25],[137.6,43.55],[135.0,50.0],
  [131.6,56.7],[127.0,62.65],[121.7,67.55],[115.6,70.8],
  [109.7,71.2],[104.4,68.7],[101.0,64.2],[100.0,58.2],
  [100.85,51.15],[102.0,44.5],[103.4,39.0]
]);
const mouthOutline = Array.from({length: 288}, (_, i) => mouthCurve.getPoint(i / 288));
const mouthTop = mouthOutline.reduce((a, b) => a.y < b.y ? a : b);
const mouthBottom = mouthOutline.reduce((a, b) => a.y > b.y ? a : b);
function mouthEdges(y) {
  if (y <= mouthTop.y) return [mouthTop.x, mouthTop.x];
  if (y >= mouthBottom.y) return [mouthBottom.x, mouthBottom.x];
  let left = Infinity, right = -Infinity;
  for (let i = 0; i < mouthOutline.length; i++) {
    const a = mouthOutline[i], b = mouthOutline[(i + 1) % mouthOutline.length];
    if ((a.y > y) === (b.y > y)) continue;
    const x = mix(a.x, b.x, (y - a.y) / (b.y - a.y));
    left = Math.min(left, x);
    right = Math.max(right, x);
  }
  return [left, right];
}

function meshGeometry(positions, indices, normals, colors) {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  if (normals) geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  else geometry.computeVertexNormals();
  if (colors) geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  return geometry;
}

function loft(rows, options = {}) {
  const at = options.at || profile(rows);
  const first = options.first ?? rows[0][0];
  const last = options.last ?? rows[rows.length - 1][0];
  const divisions = Math.ceil((last - first) / (options.cut ? .42 : .84));
  const levels = Array.from({length: divisions + 1}, (_, i) => mix(first, last, i / divisions));
  if (options.cut) {
    levels.push(mouthTop.y, mouthBottom.y);
    levels.sort((a, b) => a - b);
  }
  const floorScale = options.inset || (() => 1);
  const sample = (y, a) => ringPoint(at, y, a, floorScale(y), options.sculpt);
  const positions = [], normals = [], indices = [];
  const apertures = options.cut ? levels.map(y => {
    const [cx, rx] = at(y);
    return mouthEdges(y).map(x => Math.asin(clamp((x - cx) / rx, -1, 1)));
  }) : null;
  const strips = options.cut ? 3 : 1;
  for (let strip = 0; strip < strips; strip++) {
    const count = options.cut ? [46, 46, 69][strip] : (options.radial ?? 72);
    const start = positions.length / 3;
    for (let i = 0; i < levels.length; i++) {
      const y = levels[i];
      const bounds = !options.cut ? [-Math.PI / 2, 3 * Math.PI / 2] :
        [[-Math.PI / 2, apertures[i][0]], [apertures[i][1], Math.PI / 2],
         [Math.PI / 2, 3 * Math.PI / 2]][strip];
      for (let j = 0; j <= count; j++) {
        const a = mix(bounds[0], bounds[1], j / count);
        const p = sample(y, a);
        const dy = sample(Math.min(last, y + .019), a).sub(sample(Math.max(first, y - .019), a));
        const da = sample(y, a + .001).sub(sample(y, a - .001));
        const n = dy.cross(da).normalize();
        positions.push(p.x, p.y, p.z);
        normals.push(n.x, n.y, n.z);
        if (i < levels.length - 1 && j < count) {
          const k = start + i * (count + 1) + j;
          indices.push(k, k + count + 1, k + 1, k + 1, k + count + 1, k + count + 2);
        }
      }
    }
  }
  for (const y of [first, last]) {
    const [cx, , cz] = at(y);
    const center = positions.length / 3;
    const p = point(cx, y, cz);
    const normal = y === first ? 1 : -1;
    positions.push(p.x, p.y, p.z);
    normals.push(0, normal, 0);
    for (let i = 0; i < 48; i++) {
      const q = sample(y, tau * i / 48);
      positions.push(q.x, q.y, q.z);
      normals.push(0, normal, 0);
      const a = center + 1 + i, b = center + 1 + (i + 1) % 48;
      if (normal > 0) indices.push(center, a, b);
      else indices.push(center, b, a);
    }
  }
  return meshGeometry(positions, indices, normals);
}

const character = joint(scene, 'laughing-golden-character', 131, 160, -10);
const torso = joint(character, 'torso', 130, 149, -5);
const head = joint(torso, 'head', 123, 73, 8);
addMesh(torso, 'body-and-belly', loft(bodyRows, {
  at: bodyProfile, first: 66, sculpt: true,
  inset: y => .006 + .994 * smooth((y - 66) / 11)
}), gold);
addMesh(head, 'head-and-neck-skin', loft(bodyRows, {
  at: bodyProfile, last: 89, cut: true, sculpt: true,
  inset: y => .006 + .994 * (1 - smooth((y - 77) / 12))
}), gold);

const mouth = joint(head, 'mouth', 117, 51, 34);
const cavityRings = [
  [1.105,-.11,0xd1a240], [1.057,-.67,0xbc8934],
  [1.015,-.51,0x8c5d25], [.989,.06,0x5b351e],
  [.949,1.45,0x3c2015], [.891,3.7,0x25130f],
  [.803,7.2,0x180d0c], [.675,11.1,0x110809],
  [.46,15.8,0x0e0709], [.22,18.2,0x0d0708], [.0002,19,0x0c0708]
];
{
  const positions = [], indices = [], colors = [];
  const n = mouthOutline.length;
  const lowWall = new THREE.Color(0x4b2119);
  const lipLight = new THREE.Color(0xe6bc58);
  for (let i = 0; i < cavityRings.length; i++) {
    const [scale, depth, hex] = cavityRings[i];
    for (let j = 0; j < n; j++) {
      const contour = mouthOutline[j];
      const x = mix(116.4, contour.x, scale), y = mix(51.6, contour.y, scale);
      const p = point(x, y, faceZ(x, y) - depth);
      const color = new THREE.Color(hex);
      if (i <= 1) color.lerp(lipLight, .62 * smooth((contour.y - 53) / 22));
      if (i >= 5 && i <= 8) {
        color.lerp(lowWall, .34 * bell(contour.x, contour.y, 118, 70, 15, 8));
      }
      positions.push(p.x, p.y, p.z);
      colors.push(color.r, color.g, color.b);
      if (i < cavityRings.length - 1) {
        const k = i * n + j, next = i * n + (j + 1) % n;
        indices.push(k, next, k + n, next, next + n, k + n);
      }
    }
  }
  addMesh(mouth, 'lips-and-deep-mouth-cavity', meshGeometry(positions, indices, null, colors),
    new THREE.MeshBasicMaterial({vertexColors: true, side: THREE.DoubleSide}));
}

const upperTeeth = joint(mouth, 'upper-teeth', 120, 38, 36);
const lowerTeeth = joint(mouth, 'lower-teeth', 111, 67, 34);
const enamel = [0xfff4df,0xeee6d7,0xfff8e7,0xf2e5cb].map(color =>
  new THREE.MeshStandardMaterial({color, roughness: .46})
);
function tooth(parent, i, x, y, w, h, slant, recess, lower) {
  const geo = new THREE.SphereGeometry(1, 16, 12);
  const a = geo.attributes.position;
  const shape = (v, e) => Math.sign(v) * Math.pow(Math.abs(v), e);
  for (let j = 0; j < a.count; j++) {
    const u = a.getX(j), v = a.getY(j), z = a.getZ(j);
    const taper = 1 + v * (lower ? -.09 : .105);
    a.setXYZ(j, shape(u,.67) * w * .52 * taper, shape(v,.59) * h * .5, shape(z,.77) * 1.06);
  }
  geo.computeVertexNormals();
  geo.rotateZ(-slant);
  const p = point(x,y,faceZ(x,y) - recess);
  geo.translate(p.x,p.y,p.z);
  addMesh(parent, `tooth-${i + 1}`, geo, enamel[lower ? (i % 3 === 0 ? 1 : 3) : [0,1,0,2,1,0][i % 6]]);
}
[
